input.command:
gh api graphql -f query='
query {
  repository(owner:"ZimmermannAU", name:"zimmermann-pwa") {
    pullRequest(number: 59) {
      number
      url
      createdAt
      reviewDecision
      reviewThreads(first:100) {
        totalCount
        nodes {
          id
          isResolved
          isOutdated
          isCollapsed
          path
          line
          comments(first:30) {
            totalCount
            nodes {
              author { login }
              createdAt
              body
            }
          }
        }
      }
    }
  }
}' > /tmp/pr59_threads.json 2>&1; echo "exit=$?"; wc -c /tmp/pr59_threads.json; head -c 600 /tmp/pr59_threads.json

gh api graphql -f query='
query {
  repository(owner:"ZimmermannAU", name:"zimmermann-pwa") {
    pullRequest(number: 59) {
      reviewThreads(first:100) { nodes { isResolved resolvedBy { login } path line } }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved) | [.path, (.line|tostring), (.resolvedBy.login // "unknown")] | @tsv' 2>&1

gh api graphql -f query='
query {
  repository(owner:"ZimmermannAU", name:"zimmermann-pwa") {
    pullRequest(number: 55) {
      number url state createdAt closedAt
      reviewThreads(first:100) { totalCount nodes { isResolved path line comments(first:20){ totalCount nodes { author{login} createdAt } } } }
    }
  }
}' > /tmp/pr55.json 2>&1; jq -r '
.data.repository.pullRequest as $p |
"PR #\($p.number) \($p.state) url=\($p.url)",
"threads: \($p.reviewThreads.totalCount)",
"threads with a non-coderabbit comment: \($p.reviewThreads.nodes | map(select([.comments.nodes[].author.login] | any(.!="coderabbitai"))) | length)",
"resolved: \($p.reviewThreads.nodes | map(select(.isResolved))|length)",
"all authors seen: \([$p.reviewThreads.nodes[].comments.nodes[].author.login] | unique | join(","))"
' /tmp/pr55.json 2>&1
echo "--- PR55 issue comments (human?) ---"; gh api repos/ZimmermannAU/zimmermann-pwa/issues/55/comments --paginate --jq '.[] | [.created_at, .user.login] | @tsv' 2>&1 | sort | uniq -c | sort -rn | head
